.darma-loader-darma-b16-ai-token-stream { --accent: var(--loader-color, #6366f1); --accent-2: var(--loader-secondary-color, #c7d2fe); width: var(--loader-size, 132px); height: calc(var(--loader-size, 132px) * .22); position: relative; display: flex; gap: 3%; align-items: center; }
.darma-loader-darma-b16-ai-token-stream span { height: 100%; border-radius: 999px; background: linear-gradient(90deg, var(--accent), var(--accent-2)); transform-origin: 0 50%; transform: scaleX(0); opacity: 0; animation: darma-loader-darma-b16-ai-token-stream-token-emit calc(var(--loader-speed, 1s) * 2.6) cubic-bezier(.3, .8, .4, 1) infinite; }
.darma-loader-darma-b16-ai-token-stream span:nth-of-type(1) { width: 16%; }
.darma-loader-darma-b16-ai-token-stream span:nth-of-type(2) { width: 24%; animation-delay: calc(var(--loader-speed, 1s) * .22); }
.darma-loader-darma-b16-ai-token-stream span:nth-of-type(3) { width: 13%; animation-delay: calc(var(--loader-speed, 1s) * .44); }
.darma-loader-darma-b16-ai-token-stream span:nth-of-type(4) { width: 21%; animation-delay: calc(var(--loader-speed, 1s) * .66); }
.darma-loader-darma-b16-ai-token-stream span:nth-of-type(5) { width: 15%; animation-delay: calc(var(--loader-speed, 1s) * .88); }
.darma-loader-darma-b16-ai-token-stream .darma-loader-darma-b16-ai-token-stream__caret { position: absolute; right: 0; top: 6%; width: 2.5%; height: 88%; border-radius: 2px; background: var(--accent); animation: darma-loader-darma-b16-ai-token-stream-token-caret calc(var(--loader-speed, 1s) * .9) steps(1, end) infinite; }
@keyframes darma-loader-darma-b16-ai-token-stream-token-emit { 0%, 6% { transform: scaleX(0); opacity: 0; } 20%, 66% { transform: scaleX(1); opacity: 1; } 84%, 100% { transform: scaleX(0); opacity: 0; } }
@keyframes darma-loader-darma-b16-ai-token-stream-token-caret { 0%, 49% { opacity: 1; } 50%, 100% { opacity: .15; } }

